{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C19"],
      "claim": "GSK1322322, a piperazine-aryl-aminopyrimidine analogue, showed 77% absolute oral bioavailability in healthy volunteers after a meal, strongly supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "The same GSK1322322 scaffold in the fasted state gave 57% absolute oral bioavailability, still well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Brigatinib, sharing the piperazine-aryl-aminopyrimidine core, had approximately 46% oral bioavailability in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Trametinib, a fused heteroaromatic aniline with acetyl and methyl substituents, had 72% oral bioavailability in fasted patients, supporting high F for a structurally related core.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Brepocitinib, an aminopyrimidine with a basic amine, had 75% absolute oral bioavailability in humans, supporting high F despite basic nitrogen content.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "A close piperazine-aryl-aminopyrimidine analogue with a lactam showed approximately 20-25% oral bioavailability, at or above the threshold and therefore not contradictory to high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "High-transfer experimental analogues with piperazine-aryl-aminopyrimidine and related heteroaromatic cores consistently show oral bioavailability from 46% to 77%, well above the 20% threshold. Low-bioavailability records have zero transferability and do not apply. The physicochemical prior of low neutral fraction is real but is outweighed by direct human bioavailability evidence from close analogues.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement exists for the query molecule.",
    "The secondary piperazine may be more ionized at pH 7.4 than the methylated piperazine in some analogues, potentially lowering absorption.",
    "Food effects and formulation dependence for the query are unknown.",
    "Transporter-mediated efflux or first-pass metabolism was not experimentally assessed for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

